 if(key.startsWith('gpt:')){const idx=await readJSON('catalog/chatgpt-index.json');if(!Array.isArray(idx)||!idx.some(i=>i.name===key.slice(4)))return new Response('Video GPT inesistente',{status:404});}else if(!await env.VIDEOS.head(key))return new Response('Video inesistente',{status:404});
 const current=await readJSON('catalog/manage.json'),entry=current[key]||{};
 for(const field of ['title','description','category','project','note']){
   if(Object.hasOwn(patch,field)){if(typeof patch[field]!=='string')return new Response('Testo non valido',{status:400});entry[field]=patch[field].trim().slice(0,field==='description'||field==='note'?1200:160);}
 }
 for(const field of ['favorite','hidden'])if(Object.hasOwn(patch,field)){if(typeof patch[field]!=='boolean')return new Response('Flag non valido',{status:400});entry[field]=patch[field]}
 if(Object.hasOwn(patch,'version')){if(!['final','draft','variant','unknown'].includes(patch.version))return new Response('Versione non valida',{status:400});entry.version=patch.version}
