 const html='<!doctype html><html lang="it"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(title)+' · Video Library Studio</title>'+tags+'<style>body{font:16px system-ui;background:#0a101e;color:#f5f5ff;margin:0}main{max-width:900px;margin:30px auto;padding:18px}h1{font-size:clamp(23px,5vw,36px)}p{color:#b6c5d6}video{display:block;width:100%;max-height:74vh;background:#000;border-radius:15px}a{display:inline-block;padding:12px 16px;border-radius:10px;margin:12px 8px 0 0;background:#bea2ef;color:#1b1430;text-decoration:none;font-weight:700}a.alt{background:#26374e;color:white}</style><main><p>✦ VIDEO LIBRARY STUDIO</p><h1>'+esc(title)+'</h1><p>'+esc(desc)+'</p><video controls playsinline preload="metadata"'+(poster?' poster="'+esc(poster)+'"':'')+' src="'+esc(media)+'"></video><a href="'+esc(dl)+'">↓ Scarica MP4</a><a class="alt" href="/">← Tutti i video</a></main></html>';
